/* CSS CHÍNH: Nền đen, Tiêu đề trắng, Body trắng, Font Roboto Condensed, KHÔNG KHUNG */
    body {
        font-family: 'Roboto Condensed', sans-serif;
        line-height: 1.6;
        color: #FFFFFF; /* TOÀN BỘ CHỮ BODY MÀU TRẮNG */
        margin: 0;
        padding: 0; /* Xóa padding/margin mặc định */
        background-color: #000000; /* Nền màu ĐEN TUYỆT ĐỐI CHO CẢ TRANG */
    }

    .container {
        max-width: 900px; /* Giới hạn chiều rộng nội dung */
        margin: 20px auto; /* Căn giữa nội dung */
        padding: 20px 30px; /* Padding cho nội dung */
    }

    h1, h2, h3 {
        color: #FFFFFF; /* MÀU TRẮNG cho tiêu đề */
        font-weight: 700;
        text-transform: uppercase;
        font-family: 'Roboto Condensed' !important; /* Đảm bảo font */
    }

    h1 {
        /* Ẩn theo yêu cầu, nhưng vẫn giữ style */
        font-size: 2.5em;
        border-bottom: 3px solid #330000;
        padding-bottom: 15px;
        margin-bottom: 25px;
        text-align: center;
        letter-spacing: 1px;
    }

    h2 {
        font-size: 1.8em;
        margin-top: 30px;
        border-left: 5px solid #cc0000; /* Đỏ cho đường kẻ bên trái */
        padding-left: 10px;
    }

    p {
        margin-bottom: 15px;
        color: #FFFFFF; /* TOÀN BỘ CHỮ ĐOẠN VĂN MÀU TRẮNG */
    }

    /* Highlight và Message Cuối */
    .highlight {
        font-weight: bold;
        color: #FFFFFF; /* ĐÃ CHUYỂN THÀNH MÀU TRẮNG */
    }

    .final-message {
        color: #FFFFFF; /* ĐÃ CHUYỂN THÀNH MÀU TRẮNG */
    }

    /* Các thành phần phụ khác */
    .note {
        background-color: #331a1a;
        padding: 15px;
        border-left: 5px solid #ffcc00;
        margin: 20px 0;
        border-radius: 5px;
        color: #f0f0f0;
    }

    img {
        max-width: 100%;
        height: auto;
        display: block;
        margin: 20px auto;
        border-radius: 5px;
    }

    /* Link trong bài */
    a {
        color: #ff3333; /* Màu đỏ sáng cho link để nổi bật */
        text-decoration: none;
    }

    a:hover {
        text-decoration: underline;
    }

    /* Chú thích ảnh */
    em {
        font-size: 0.9em;
        color: #AAAAAA;
        font-style: italic;
    }

    /* Danh sách */
    ul {
        padding-left: 20px;
    }

    li {
        margin-bottom: 10px;
        color: #FFFFFF;
    }

    /* --- TỐI ƯU BẢNG (TABLE) --- */
    .table-wrapper {
        overflow-x: auto; /* Cho phép trượt ngang trên mobile */
        -webkit-overflow-scrolling: touch; /* Tăng mượt cho iOS */
        margin: 20px 0;
    }

    table {
        width: 100%;
        min-width: 800px; /* Đặt chiều rộng tối thiểu để bảng không bị bóp méo */
        border-collapse: collapse;
        color: #FFFFFF;
        background-color: #222222;
    }

    th, td {
        border: 1px solid #444444;
        padding: 10px;
        text-align: center; /* Đã định nghĩa ở đây */
        font-size: 0.9em;
        vertical-align: middle;
    }

    th {
        background-color: #333333;
        text-transform: uppercase;
    }
/* --- CSS TÙY CHỈNH CHO BÀI VIẾT TGP --- */

/* Cài đặt container nội dung */
.tgp-article-container {
    max-width: 900px; /* Giới hạn chiều rộng nội dung */
    margin: 20px auto; /* Căn giữa nội dung */
    padding: 20px 30px; /* Padding cho nội dung */
    /* Quan trọng: Đảm bảo màu chữ/nền không bị CSS website ghi đè */
    background-color: #000000 !important; /* Nền đen tuyệt đối */
    color: #FFFFFF !important; /* Chữ trắng */
}

/* Tiêu đề */
.tgp-article-container h1, 
.tgp-article-container h2, 
.tgp-article-container h3 {
    color: #FFFFFF;
    font-weight: 700;
    text-transform: uppercase;
    font-family: 'Roboto Condensed', sans-serif !important;
}

.tgp-article-container h1 {
    font-size: 2.5em;
    border-bottom: 3px solid #330000;
    padding-bottom: 15px;
    margin-bottom: 25px;
    text-align: center;
    letter-spacing: 1px;
}

.tgp-article-container h2 {
    font-size: 1.8em;
    margin-top: 30px;
    border-left: 5px solid #cc0000;
    padding-left: 10px;
}

/* Đoạn văn bản */
.tgp-article-container p {
    margin-bottom: 15px;
    color: #FFFFFF;
}

/* Link */
.tgp-article-container a {
    color: #ff3333; /* Màu đỏ sáng cho link */
    text-decoration: none;
}

.tgp-article-container a:hover {
    text-decoration: underline;
}

/* Hình ảnh */
.tgp-article-container img {
    max-width: 100%;
    height: auto;
    display: block;
    margin: 20px auto;
    border-radius: 5px;
}

/* Danh sách */
.tgp-article-container ul {
    padding-left: 20px;
}

.tgp-article-container li {
    margin-bottom: 10px;
    color: #FFFFFF;
}

/* --- TỐI ƯU BẢNG (TABLE) --- */
.tgp-article-container .table-wrapper {
    overflow-x: auto; /* Cho phép trượt ngang trên mobile */
    -webkit-overflow-scrolling: touch;
    margin: 20px 0;
}

.tgp-article-container table {
    width: 100%;
    min-width: 800px;
    border-collapse: collapse;
    color: #FFFFFF;
    background-color: #222222;
}

.tgp-article-container th, 
.tgp-article-container td {
    border: 1px solid #444444;
    padding: 10px;
    text-align: center;
    font-size: 0.9em;
    vertical-align: middle;
}

.tgp-article-container th {
    background-color: #333333;
    text-transform: uppercase;
}

/* --- TỐI ƯU CHO MOBILE --- */
@media (max-width: 768px) {
    .tgp-article-container {
        padding: 20px 15px;
        margin: 0 auto;
    }

    .tgp-article-container h1 {
        font-size: 2em;
    }

    .tgp-article-container h2 {
        font-size: 1.5em;
    }
}
/* --- HẾT CSS TÙY CHỈNH --- */

    /* --- TỐI ƯU CHO MOBILE --- */
    @media (max-width: 768px) {
        .container {
            padding: 20px 15px; /* Giảm padding lề trái/phải trên mobile */
            margin: 0 auto; /* Xóa margin trên/dưới */
        }

        h1 {
            font-size: 2em; /* Giảm cỡ chữ h1 */
        }

        h2 {
            font-size: 1.5em; /* Giảm cỡ chữ h2 */
        }
    }
